function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
function safeText(value){return String(value||'Request failed').split(/\r?\n/,1)[0].replace(/[A-Za-z]:\\[^\s\"']+/g,'<internal-path>').replace(/(^|\s)\/(?:[^\/\s]+\/)+[^\s\"']+/g,'$1<internal-path>').replace(/\b[a-fA-F0-9]{40,64}\b/g,'<internal-id>').slice(0,500)}
async function get(path){const response=await fetch(origin()+path,{headers:{Accept:'application/json'}});let payload=null;try{payload=await response.json()}catch{}if(!response.ok){const detail=payload&&payload.detail!==undefined?payload.detail:payload||{};const error=detail&&typeof detail==='object'?detail:{};throw new Error(JSON.stringify({status:'failed',error_code:String(error.code||'WORKSPACE_CONTEXT_FAILED'),error_summary:safeText(error.message||detail),http_status:response.status}))}return payload}
async function run(input){const backtestLimit=Math.max(1,Math.min(20,Number(input.backtest_limit||5))),syncLimit=Math.max(1,Math.min(20,Number(input.sync_job_limit||5)));return get('/api/agent/context?backtest_limit='+backtestLimit+'&sync_job_limit='+syncLimit)}
